cypress_script:
describe('Select Menu Widgets', () => {
  it('should select a car from the dropdown successfully', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('select#cars').select('Volvo').should('have.value', 'volvo');
  });
  it('should not change the URL when no selection is made', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('select#cars').select('').should('have.value', '');
    cy.url().should('eq', 'https://demoqa.com/select-menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Select Menu Widgets', () => {
  test('should select a car from the dropdown successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('select#cars', 'volvo');
    const value = await page.locator('select#cars').inputValue();
    expect(value).toBe('volvo');
  });

  test('should not change the URL when no selection is made', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('select#cars', '');
    const value = await page.locator('select#cars').inputValue();
    expect(value).toBe('');
    expect(page.url()).toBe('https://demoqa.com/select-menu');
  });
});
